export const scenarios=rows.map(([track,id,title,role,stage,goal,opener,words,patterns])=>({track,id,title,role,stage,goal,opener,words:words.split('|').map(p=>{const [en,zh]=p.split(':');return {id:id+'-'+en,en,zh,category:tracks[track],simple:zh,example:patterns.split('|').find(s=>s.toLowerCase().includes(en.toLowerCase()))||`Could you explain ${en} in this context?`,usage:`在「${title}」中，用来谈论${zh}。`,sceneId:id}}),patterns:patterns.split('|'),challenge:`不看完整示范，${goal}；回答一个临场追问。`}));
export const vocabulary=scenarios.flatMap(s=>s.words);
export function stageProgress(evidence,track,now=Date.now()){
 const rows=evidence.filter(e=>e.track===track&&e.independent&&e.quote&&e.passed);
 const criteria=stages.map((title,i)=>{const r=rows.filter(e=>e.stage===i+1),contexts=new Set(r.map(e=>e.sceneId));const delayed=r.some(a=>r.some(b=>a.sessionId!==b.sessionId&&new Date(a.date)-new Date(b.date)>=86400000));return {stage:i+1,title,contexts:contexts.size,delayed,complete:contexts.size>=2&&delayed,evidence:r}});
 let achieved=0;for(const c of criteria){if(!c.complete)break;achieved=c.stage}
 return {achieved,criteria,next:criteria.find(c=>!c.complete),assessed:rows.length>0};
}
export function nextReview(card,passed,now=Date.now()){const n=passed?Math.min((card.step||0)+1,4):0;return {...card,step:n,due:new Date(now+[1,3,7,14,30][n]*86400000).toISOString(),lastReviewed:new Date(now).toISOString(),attempts:(card.attempts||0)+1}}

export function challengeGoal(stage,scene){return [
 `在「${scene.title}」中，用自己的英语说明一个需求，并回答一个简短追问。`,
 `在「${scene.title}」中，独立完成一次具体安排：确认时间、数量、地点或费用，并核对对方回答。`,
 `围绕「${scene.title}」自然展开交流：主动追问一次，并对对方的新信息作相关回应。`,
 `在「${scene.title}」中，解释一个具体问题及原因，提出解决方案，并处理对方的异议。`,
 `在「${scene.title}」相关工作讨论中，介绍方案、澄清需求并确认具体下一步。`,
 `围绕「${scene.title}」处理复杂协商：明确边界、提出条件交换、回应反对意见，并总结共识与待定事项。`
][stage-1]}
